INSERT INTO public.tour_product_pages (
  slug, locale, product_id, is_published, sort_order, tour_id,
  title, subtitle, region_label, duration_label, stops_count,
  rating_avg, review_count, badges, hero_image_url, thumbnail_url,
  card_short_description, seo_title, meta_description,
  headline_line_1, headline_line_2,
  price_amount_label, price_currency, price_per, detail_payload
) VALUES (
  'busan-small-group-yonggungsa-skycapsule-gamcheon-tour',
  'zh-TW',
  'busan-small-group-yonggungsa-skycapsule-gamcheon-tour',
  TRUE,
  1,
  (SELECT id FROM public.tours WHERE slug = 'busan-small-group-yonggungsa-skycapsule-gamcheon-tour' LIMIT 1),
  '釜山小團體：海東龍宮寺·天空膠囊·文化村',
  '一天串聯釜山海岸名勝與山坡村落的小團體之旅 — 海東龍宮寺、青沙浦踏石展望台（玻璃天空步道）、藍線公園天空膠囊（預訂時可選含票／不含票）、甘川文化村，以及擁有「希望階梯」單軌的寧靜닥밭골（Dakbatgol）壁畫村。',
  '釜山',
  '≈ 10小時',
  8,
  0,
  0,
  '["小團體","釜山","天空膠囊","海岸","文化村"]'::jsonb,
  '/images/tours/haedong-yonggungsa/haedong-yonggungsa-sunrise-cliff.webp',
  '/images/tours/haedong-yonggungsa/haedong-yonggungsa-sunrise-cliff.webp',
  '以海岸與山坡村落為軸心的釜山小團體一日遊。清幽上午時段的海東龍宮寺、免費玻璃地板的青沙浦踏石展望台、青沙浦→尾浦的藍線公園天空膠囊（預訂時選擇含票或不含票）、午餐、甘川文化村，以及免費單軌沿「希望階梯」上行的私房景點Dakbatgol壁畫村。除可選的膠囊外，所有核心停留點皆免費入場。',
  '釜山小團體遊：海東龍宮寺·天空膠囊·甘川 | AtoC Korea',
