  detail_payload = EXCLUDED.detail_payload,
  updated_at = NOW();

-- 3) tour_product_offers — base (ticket excluded, default) + ticket-included
INSERT INTO public.tour_product_offers (
  tour_product_page_id, label, amount_minor, currency, stripe_price_id, is_active, is_default
)
SELECT p.id, 'Sky Capsule ticket excluded (base)', 5900, 'USD', NULL, TRUE, TRUE
FROM public.tour_product_pages p
WHERE p.slug = 'busan-small-group-yonggungsa-skycapsule-gamcheon-tour' AND p.locale = 'en'
  AND NOT EXISTS (
    SELECT 1 FROM public.tour_product_offers o WHERE o.tour_product_page_id = p.id AND o.is_default
  );

INSERT INTO public.tour_product_offers (
  tour_product_page_id, label, amount_minor, currency, stripe_price_id, is_active, is_default
)
SELECT p.id, 'Sky Capsule ticket included (2-per-capsule basis)', 7900, 'USD', NULL, TRUE, FALSE
FROM public.tour_product_pages p
WHERE p.slug = 'busan-small-group-yonggungsa-skycapsule-gamcheon-tour' AND p.locale = 'en'
  AND NOT EXISTS (
    SELECT 1 FROM public.tour_product_offers o
    WHERE o.tour_product_page_id = p.id AND o.label = 'Sky Capsule ticket included (2-per-capsule basis)'
  );

COMMIT;

